<!doctype html>
<html lang="{{ str_replace('_','-',app()->getLocale()) }}">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>News & Updates — {{ $brand['name'] ?? config('app.name') }}</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css"><style>:root{--bg:#031018;--card:rgba(9,39,52,.82);--line:rgba(110,220,240,.14);--text:#edfaff;--muted:#8caab7;--accent:#45c8e8}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% 0,rgba(69,200,232,.15),transparent 35%),var(--bg);color:var(--text);font-family:Inter,system-ui,sans-serif}a{color:inherit;text-decoration:none}.shell{width:min(1120px,calc(100% - 28px));margin:auto}.header{position:sticky;top:0;z-index:10;background:rgba(3,16,24,.86);backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.nav{min-height:68px;display:flex;align-items:center;justify-content:space-between;gap:15px}.brand{font-weight:800;display:flex;align-items:center;gap:9px}.brand img{width:36px;height:36px;object-fit:contain;border-radius:9px}.navlinks{display:flex;gap:5px}.navlinks a{padding:9px 11px;color:var(--muted);font-size:11px;border-radius:9px}.navlinks a:hover{background:rgba(69,200,232,.08);color:var(--text)}.hero{padding:70px 0 35px}.eyebrow{font-size:10px;letter-spacing:.18em;color:var(--accent);text-transform:uppercase}.hero h1{font-size:clamp(38px,6vw,68px);line-height:1;margin:10px 0}.hero p{color:var(--muted);max-width:680px;line-height:1.7}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;padding-bottom:50px}.card{border:1px solid var(--line);border-radius:20px;overflow:hidden;background:linear-gradient(145deg,var(--card),rgba(5,24,33,.82));transition:.25s}.card:hover{transform:translateY(-4px);border-color:rgba(69,200,232,.35)}.thumb{height:180px;background:radial-gradient(circle at 50% 50%,rgba(69,200,232,.18),transparent 45%),#061923;display:grid;place-items:center;overflow:hidden}.thumb img{width:100%;height:100%;object-fit:cover}.thumb i{font-size:38px;color:#45c8e8;filter:drop-shadow(0 0 16px rgba(69,200,232,.45))}.body{padding:18px}.date{color:#6f9aa8;font-size:10px}.body h2{font-size:18px;margin:8px 0}.body p{color:var(--muted);font-size:12px;line-height:1.65}.read{display:inline-flex;gap:7px;align-items:center;color:var(--accent);font-size:11px;font-weight:700;margin-top:8px}.empty{padding:35px;border:1px dashed var(--line);border-radius:18px;color:var(--muted)}.pager{padding:20px 0 55px}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:540px){.navlinks a:not(:first-child){display:none}.hero{padding:48px 0 25px}.grid{grid-template-columns:1fr}.thumb{height:200px}}</style></head>
<body><header class="header"><div class="shell nav"><a class="brand" href="{{ route('home') }}">@if(!empty($brand['logo_path']))<img src="{{ asset('storage/'.$brand['logo_path']) }}" alt="">@endif<span>{{ $brand['name'] ?? config('app.name') }}</span></a><nav class="navlinks"><a href="{{ route('home') }}"><i class="fa-solid fa-house"></i> Home</a><a href="{{ route('news.index') }}"><i class="fa-regular fa-newspaper"></i> News</a><a href="https://mail.fuelfreepowerplant.com"><i class="fa-solid fa-envelope"></i> Webmail</a></nav></div></header><main class="shell"><section class="hero"><span class="eyebrow">Company updates</span><h1>News & Updates</h1><p>Latest published updates, announcements and developments from {{ $brand['name'] ?? 'FuelFree PowerPlant' }}.</p></section>@if($news->isEmpty())<div class="empty">No published news is available yet.</div>@else<div class="grid">@foreach($news as $item)<article class="card"><div class="thumb">@if($item->image_path)<img src="{{ asset('storage/'.$item->image_path) }}" alt="{{ $item->title }}" loading="lazy">@else<i class="fa-regular fa-newspaper"></i>@endif</div><div class="body"><span class="date">{{ $item->published_at?->format('d M Y') ?? 'Company update' }}</span><h2>{{ $item->title }}</h2><p>{{ $item->excerpt ?: \Illuminate\Support\Str::limit(strip_tags($item->content),150) }}</p><a class="read" href="{{ route('news.show',$item->slug) }}">Read update <i class="fa-solid fa-arrow-right"></i></a></div></article>@endforeach</div><div class="pager">{{ $news->links() }}</div>@endif</main></body></html>
